    '<b>Branco</b><span>#FFFFFF</span>': ['<b>White</b><span>#FFFFFF</span>', '<b>Blanco</b><span>#FFFFFF</span>'],
    '<span class="pp2-fx" aria-hidden="true"></span><b>4</b><span>causas em campo: saúde mental, racismo, sustentabilidade e igualdade de gênero</span>': ['<span class="pp2-fx" aria-hidden="true"></span><b>4</b><span>causes on the field: mental health, racism, sustainability and gender equality</span>', '<span class="pp2-fx" aria-hidden="true"></span><b>4</b><span>causas en la cancha: salud mental, racismo, sostenibilidad e igualdad de género</span>'],
    '<span class="pp2-fx" aria-hidden="true"></span><b>3</b><span>versões do site: desktop, tablet e celular</span>': ['<span class="pp2-fx" aria-hidden="true"></span><b>3</b><span>site versions: desktop, tablet and mobile</span>', '<span class="pp2-fx" aria-hidden="true"></span><b>3</b><span>versiones del sitio: escritorio, tablet y móvil</span>'],
    '<span class="pp2-fx" aria-hidden="true"></span><b>1</b><span>página com tudo: ingresso, agenda, programação e apoiadores</span>': ['<span class="pp2-fx" aria-hidden="true"></span><b>1</b><span>page with everything: tickets, schedule, program and supporters</span>', '<span class="pp2-fx" aria-hidden="true"></span><b>1</b><span>página con todo: entradas, agenda, programación y patrocinadores</span>'],
    'Precisa de um site à altura do seu evento?': ['Need a website worthy of your event?', '¿Necesitas un sitio a la altura de tu evento?'],
    'Site do Jogo pela Integridade no desktop (role para ver)': ['Game for Integrity site on desktop (scroll to see)', 'Sitio del Partido por la Integridad en escritorio (desplázate para ver)'],
    'Site do Jogo pela Integridade no celular (role para ver)': ['Game for Integrity site on mobile (scroll to see)', 'Sitio del Partido por la Integridad en el móvil (desplázate para ver)'],
    'Topo do site: Jogo pela Integridade 2026 no Estádio Morumbis': ['Top of the site: Game for Integrity 2026 at Morumbis Stadium', 'Parte superior del sitio: Partido por la Integridad 2026 en el Estadio Morumbis'],
    'Sobre o jogo e as quatro causas em campo': ['About the game and the four causes on the field', 'Sobre el partido y las cuatro causas en la cancha'],
    'Marque na agenda: data, horário, local e entrada': ['Save the date: date, time, venue and entry', 'Agéndalo: fecha, horario, lugar y entrada'],
    'Jogadores convocados vestindo a camisa': ['Called-up players wearing the jersey', 'Jugadores convocados con la camiseta'],
    'Programação do dia': ['Program of the day', 'Programación del día'], 'Apoiadores por categoria': ['Supporters by category', 'Patrocinadores por categoría'],
