    '<span class="pp2-fx" aria-hidden="true"></span><b>+600</b><span>produtos entre medicamentos, vitaminas, higiene e beleza</span>': ['<span class="pp2-fx" aria-hidden="true"></span><b>+600</b><span>products across medicines, vitamins, hygiene and beauty</span>', '<span class="pp2-fx" aria-hidden="true"></span><b>+600</b><span>productos entre medicamentos, vitaminas, higiene y belleza</span>'],
    '<span class="pp2-fx" aria-hidden="true"></span><b>100%</b><span>verticalizada, do desenvolvimento à distribuição</span>': ['<span class="pp2-fx" aria-hidden="true"></span><b>100%</b><span>vertically integrated, from development to distribution</span>', '<span class="pp2-fx" aria-hidden="true"></span><b>100%</b><span>verticalizada, del desarrollo a la distribución</span>'],
    '<span class="pp2-fx" aria-hidden="true"></span><b>1977</b><span>o ano em que a Cimed começou a levar saúde ao Brasil</span>': ['<span class="pp2-fx" aria-hidden="true"></span><b>1977</b><span>the year Cimed started bringing healthcare to Brazil</span>', '<span class="pp2-fx" aria-hidden="true"></span><b>1977</b><span>el año en que Cimed empezó a llevar salud a Brasil</span>'],
