    '<span class="pp2-fx" aria-hidden="true"></span><b>111</b><span>sessões em 2 dias, 9 salas e 7 hubs temáticos</span>': ['<span class="pp2-fx" aria-hidden="true"></span><b>111</b><span>sessions over 2 days, 9 rooms and 7 themed hubs</span>', '<span class="pp2-fx" aria-hidden="true"></span><b>111</b><span>sesiones en 2 días, 9 salas y 7 hubs temáticos</span>'],
    '<span class="pp2-fx" aria-hidden="true"></span><b>2</b><span>versões do site para o evento, no desktop e no celular</span>': ['<span class="pp2-fx" aria-hidden="true"></span><b>2</b><span>versions of the event site, on desktop and mobile</span>', '<span class="pp2-fx" aria-hidden="true"></span><b>2</b><span>versiones del sitio del evento, en escritorio y móvil</span>'],
    'Palco do Impacta Mais 2025': ['Impacta Mais 2025 stage', 'Escenario de Impacta Mais 2025'],
    'Painel do Impacta Mais 2025': ['Impacta Mais 2025 panel', 'Panel de Impacta Mais 2025'],
    'Público no Fórum de Economia de Impacto': ['Audience at the Impact Economy Forum', 'Público en el Foro de Economía de Impacto'],
