    '<span class="pp2-fx" aria-hidden="true"></span><b>+35%</b><span>em vendas depois da nova marca</span>': ['<span class="pp2-fx" aria-hidden="true"></span><b>+35%</b><span>in sales after the new brand</span>', '<span class="pp2-fx" aria-hidden="true"></span><b>+35%</b><span>en ventas después de la nueva marca</span>'],
    '<span class="pp2-fx" aria-hidden="true"></span><b>8</b><span>aplicações da marca, do pacote à fachada da fábrica</span>': ['<span class="pp2-fx" aria-hidden="true"></span><b>8</b><span>brand applications, from the package to the factory façade</span>', '<span class="pp2-fx" aria-hidden="true"></span><b>8</b><span>aplicaciones de la marca, del paquete a la fachada de la fábrica</span>'],
